<script setup lang="ts">
type User={id:string;name:string;email:string;createdAt:string};const config=useRuntimeConfig();const api=String(config.public.apiBase||"");const user=ref<User|null>(null);const loading=ref(true);const error=ref("");try{const r=await $fetch<{user:User;message?:string}>(`${api}/api/session/me`,{credentials:"include"});user.value=r.user}catch(e:any){error.value=e?.data?.message||"Unable to load your account."}finally{loading.value=false}
</script>
<template><main class="mx-auto max-w-4xl space-y-6 p-5 sm:p-8"><div class="mb-4"><DashboardBackToDashboard /></div><DashboardNav/><header><p class="text-xs font-semibold uppercase tracking-widest text-[var(--vl-sage-dark)]">System</p><h1 class="mt-2 text-3xl font-semibold">Settings</h1><p class="mt-2 text-sm text-[var(--vl-muted)]">Your authenticated account and session details.</p></header><div v-if="loading" class="rounded-2xl bg-white/70 p-7">Loading account…</div><div v-else-if="error" class="rounded-2xl border border-red-200 p-6">{{error}} <NuxtLink to="/auth/login" class="underline">Sign in</NuxtLink></div><template v-else-if="user"><section class="rounded-2xl border border-[var(--vl-border)] bg-white/70 p-6"><h2 class="font-semibold">Profile</h2><dl class="mt-4 grid gap-4 sm:grid-cols-2"><div><dt class="text-xs text-[var(--vl-muted)]">Name</dt><dd class="mt-1">{{user.name}}</dd></div><div><dt class="text-xs text-[var(--vl-muted)]">Email</dt><dd class="mt-1">{{user.email}}</dd></div></dl></section><section class="rounded-2xl border border-[var(--vl-border)] bg-white/70 p-6"><h2 class="font-semibold">Account</h2><p class="mt-3 text-sm">Member since {{new Date(user.createdAt).toLocaleDateString()}}</p><p class="mt-1 text-xs text-[var(--vl-muted)]">Account ID: {{user.id}}</p></section><section class="rounded-2xl border border-[var(--vl-border)] bg-white/70 p-6"><h2 class="font-semibold">Security</h2><p class="mt-3 text-sm">You are signed in using VeriLens Credentials authentication.</p><p class="mt-1 text-sm text-[var(--vl-muted)]">Password changes are currently unavailable. Your session is managed by Auth.js.</p></section></template></main></template>

